import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserProfileServlet.class.getName());

    // Connection pool managed by container
    private javax.sql.DataSource ds;

    @Override
    public void init() throws ServletException {
        try {
            javax.naming.InitialContext ctx = new javax.naming.InitialContext();
            ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/userdb");
        } catch (Exception e) {
            throw new ServletException("Failed to initialize datasource", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric to prevent injection there
        if (!userId.matches("\\d+")) {
            resp.sendError(400, "Invalid id format");
            return;
        }

        // fields parameter allows caller to select which columns to return
        // Default fields if not specified
        if (fields == null || fields.isEmpty()) {
            fields = "username, email, display_name";
        }

        // Basic sanitization - remove obvious dangerous characters
        // NOTE: This is NOT sufficient protection against all SQLi variants
        fields = fields.replaceAll("[;]", "");

        String query = "SELECT " + fields + " FROM user_profiles WHERE user_id = " + userId;
        log.info("Executing query for user " + userId);

        try (Connection conn = ds.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();

            if (rs.next()) {
                ResultSetMetaData meta = rs.getMetaData();
                StringBuilder json = new StringBuilder("{");
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\":");
                    String val = rs.getString(i);
                    if (val == null) {
                        json.append("null");
                    } else {
                        json.append("\"").append(val.replace("\"", "\\\"")).append("\"");
                    }
                }
                json.append("}");
                out.print(json.toString());
            } else {
                resp.sendError(404, "User not found");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String userId = req.getParameter("id");
        String bio = req.getParameter("bio");
        String website = req.getParameter("website");

        if (userId == null || !userId.matches("\\d+")) {
            resp.sendError(400, "Invalid id");
            return;
        }

        // Use prepared statement for updates (safe)
        String update = "UPDATE user_profiles SET bio = ?, website = ? WHERE user_id = ?";

        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(update)) {
            ps.setString(1, bio);
            ps.setString(2, website);
            ps.setInt(3, Integer.parseInt(userId));
            int rows = ps.executeUpdate();

            resp.setContentType("application/json");
            resp.getWriter().print("{\"updated\":" + rows + "}");
        } catch (SQLException e) {
            log.warning("Update failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
